package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, bad := nextInt(), nextInt()
	if bad == 0 {
		w.WriteString("-1\n")
		return
	}
	total := n * (n + 1) / 2
	for j := int64(1); j <= n; j++ {
		if j*(j+1)/2 == bad {
			total--
			break
		}
	}
	w.WriteString(strconv.FormatInt(total, 10) + "\n")
}
